import{_ as o,l as n,o as a,c as l,v as t,p as s,x as r,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"代际流动与人力资本","description":"","frontmatter":{"title":"代际流动与人力资本","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/intergenerational-mobility.md","filePath":"econ/intergenerational-mobility.md","lastUpdated":1789023840000}'),c={name:"econ/intergenerational-mobility.md"};function m(h,e,A,B,_,u){const i=n("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="代际流动与人力资本" tabindex="-1">代际流动与人力资本 <a class="header-anchor" href="#代际流动与人力资本" aria-label="Permalink to &quot;代际流动与人力资本&quot;">​</a></h1><div class="epigraph"><p>财富可以乘性滚；技能与邻里把收入过程变成跨代马尔可夫，尾与机会不是同一张图。</p><footer>—— Becker and Tomes, Human Capital and the Rise and Fall of Families, JLaborE 1986；Chetty, Hendren, Kline and Saez 的美国流动地图</footer></div><p><a href="/econ/inequality-r-g">上一课</a>谈财富相对增长的膨胀。收入机会可以在财富份额上升时改善或恶化。本课缺口是<strong>代际</strong>：人力资本投资与邻里如何把 \\(z\\) 的马尔可夫从一代接到下一。不重写 \\(r\\gt g\\) 会计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Becker–Tomes：父母最大化子女人力资本加遗产，信贷约束使穷父母投资不足，能力回归均值但约束造成持久。Solon 的代际收入弹性；Chetty 等用税收行政数据画通勤区流动。缺口是给 Aiyagari 的外生 \\(z\\) 过程一个跨代来源，而不是再校准一年一度的劳动收入 viscocity。</p><p><span class="marginnote">Becker and Tomes, <em>JOLE</em> 1986。Chetty et al., <em>QJE</em> 2014（Equality of Opportunity）。Restuccia–Urrutia、Lee–Seshadri 的定量人力资本宏观。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把世代交叠或「王朝」里的教育选择写成贝尔曼：状态含父母财富与子女能力。一般均衡：技能供给改工资升水，从而改教育回报。邻里、学校质量作为外生或作为地方均衡（教育财政）。流动统计：秩–秩斜率、顶层到下层的转移矩阵，不是只有基尼。</p>',8)),(a(),s(p,null,{default:r(()=>[E(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAR%5B%22%E7%88%B6%E6%AF%8D%E8%B4%A2%E5%AF%8C%20%2F%20%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20EDU%5B%22%E4%BA%BA%E5%8A%9B%E8%B5%84%E6%9C%AC%E6%8A%95%E8%B5%84%22%5D%0A%20%20ABL%5B%22%E8%83%BD%E5%8A%9B%22%5D%20--%3E%20EDU%0A%20%20EDU%20--%3E%20Z%5B%22%E5%AD%90%E5%A5%B3%E6%94%B6%E5%85%A5%E8%BF%87%E7%A8%8B%22%5D%0A%20%20Z%20--%3E%20MOB%5B%22%E4%BB%A3%E9%99%85%E5%BC%B9%E6%80%A7%22%5D%0A%20%20NEI%5B%22%E9%82%BB%E9%87%8C%20%2F%20%E5%AD%A6%E6%A0%A1%22%5D%20--%3E%20EDU%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与厚尾：创业与收益异质造财富尾；教育造收入过程的持久。政策：公立教育、地区迁移（Chetty–Hendren 的移动实验）改的是 \\(z\\) 的转移，不是一次性 MPC。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是约束下的投资与均值回归的竞赛。完全信贷时，能力高的孩子总能受教育，流动由能力遗传决定；约束时财富本身成为机会。宏观含义：收入风险不完全是保险问题（后课），也是事前投资问题。HANK 的季度 MPC 不回答「这个通勤区的孩子能否翻身」。</p><p><span class="marginnote">本课不把邻里效应写成流行病学。也不把高考制度写成一般理论。定量宏观用的是教育生产函数与税收数据矩。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评价每一项教育政策。不把文化叙事当识别。种族、性别的全部经验文献放不下，只保留装置：约束、生产函数、地方公共品。移民与开放另课。</p><p>后课默认：外生收入马尔可夫可以来自代际人力资本；流动统计与财富尾分开报告。下一课：一代之内，劳动收入风险如何被市场与家庭保险。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Becker–Tomes：约束使人力资本投资依赖父母财富。</li><li>流动用转移矩阵与秩弹性，不只基尼。</li><li>与 \\(r\\gt g\\) 的财富故事时间尺度和机制都不同。</li><li>出处：Becker and Tomes, <em>JOLE</em> 1986；Chetty et al., <em>QJE</em> 2014。</li></ul>',9))])}const C=o(c,[["render",m]]);export{T as __pageData,C as default};
